def note(task_id: str) -> tuple[str, str]:
    status, en, pt = C[T[task_id]]
    sid, en_name, pt_name = STATUS[status]
    text = f"PT-BR: {pt_name}. {pt}\n\nEN: {en_name}. {en}\n\n{SIGNATURE}"
    return sid, text


def main() -> None:
    tasks = json.loads(Path(sys.argv[1]).read_text(encoding="utf-8"))["results"] if len(sys.argv) > 1 else None
    ids = [t["task_id"] for t in tasks] if tasks else sorted(T)
    missing = [i for i in ids if i not in T]
    if missing:
        raise SystemExit(f"Unmapped tasks: {missing}")
    out = {i: dict(zip(("status", "note"), note(i))) for i in ids}
    root = Path(__file__).resolve().parent
    if len(sys.argv) > 2:
        Path(sys.argv[2]).write_text(json.dumps(out, ensure_ascii=False, indent=1), encoding="utf-8")
    titles = {t["task_id"]: (t["title"], t["url"].split("/phase/")[1].split("/")[0]) for t in tasks} if tasks else {}
    counts = {"DONE": 0, "TODO": 0, "NA": 0}
    rows = []
    for i in ids:
        status = C[T[i]][0]
        counts[status] += 1
        title, phase = titles.get(i, ("", ""))
        rows.append(f"| {i} | {phase} | {title.replace('|', '/')} | {STATUS[status][1]} | {C[T[i]][1].replace('|', '/')} |")
    md = [
        "# Security controls - SD Elements mapping",
        "",
        "Project: **ACME Clinical - Ward Patient Monitoring** (SD Elements project 27). Generated by `docs/security/sde_assessment.py`.",
        "",
        f"Summary: **{counts['DONE']} Complete**, **{counts['TODO']} Incomplete**, **{counts['NA']} Not Applicable** "
        f"(total {sum(counts.values())}). Incomplete items are mostly organisational processes, deployment-time platform "
        "configuration and assessments (SAST/DAST/pentest/code review) that cannot be evidenced from the code alone.",
        "",
        "| ID | Phase | Countermeasure | Status | Evidence |",
        "| --- | --- | --- | --- | --- |",
        *rows,
        "",
    ]
    (root / "controls.md").write_text("\n".join(md), encoding="utf-8")
    print(counts)


if __name__ == "__main__":
    main()
